def search_hotels(latitude, longitude, name=None, check_in_date=None, check_out_date=None, adults=None, children=None, search_context=None, facilities=None, **_extra):
    import json, os, datetime, time, re, random, math

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0017000" if __import__("os").path.isdir("./environment_mix/0017000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    _now = _now_dt.isoformat() + "Z"

    def _log(status, endpoint="search-hotels", message=None, extra=None, latency_ms=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            row = {
                "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
                "endpoint": endpoint,
                "status": status,
                "timestamp": _now,
                "latency_ms": latency_ms if latency_ms is not None else int((time.time() - _t0) * 1000),
            }
            if message is not None:
                row["message"] = message
            if isinstance(extra, dict) and extra:
                row["extra"] = extra
            logs.append(row)
            _save("request_logs.json", logs)

    def _rate_limited():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return False
        now_dt = datetime.datetime.utcnow()
        cutoff_min = now_dt - datetime.timedelta(seconds=60)
        cutoff_day = now_dt - datetime.timedelta(hours=24)
        c_min = 0
        c_day = 0
        for r in logs[-8000:]:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "search-hotels":
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                t = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if t >= cutoff_day:
                c_day += 1
                if t >= cutoff_min:
                    c_min += 1
        return (c_min >= 30) or (c_day >= 500)

    if _rate_limited():
        _log("error", message="rate limit exceeded")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # ---- validate inputs ----
    if not isinstance(latitude, (int, float)) or not isinstance(longitude, (int, float)):
        _log("error", message="validation error", extra={"field": "latitude/longitude"})
        return _err("VALIDATION_ERROR", "latitude and longitude must be numbers")
    latitude = float(latitude)
    longitude = float(longitude)
    if not (-90.0 <= latitude <= 90.0):
        _log("error", message="validation error", extra={"field": "latitude"})
        return _err("VALIDATION_ERROR", "latitude must be between -90 and 90", field="latitude")
    if not (-180.0 <= longitude <= 180.0):
        _log("error", message="validation error", extra={"field": "longitude"})
        return _err("VALIDATION_ERROR", "longitude must be between -180 and 180", field="longitude")

    if check_in_date is None:
        check_in_date = "2025-06-25"
    if check_out_date is None:
        check_out_date = "2025-06-26"

    if not isinstance(check_in_date, str) or not isinstance(check_out_date, str):
        _log("error", message="validation error", extra={"field": "check_in_date/check_out_date"})
        return _err("VALIDATION_ERROR", "check_in_date and check_out_date must be strings (YYYY-MM-DD)")

    def _parse_date(s):
        return datetime.date.fromisoformat(s)

    try:
        cin = _parse_date(check_in_date)
        cout = _parse_date(check_out_date)
    except Exception:
        _log("error", message="validation error", extra={"field": "check_in_date/check_out_date"})
        return _err("VALIDATION_ERROR", "Invalid date format; expected YYYY-MM-DD", field="check_in_date/check_out_date")

    if not (cout > cin):
        _log("error", message="validation error", extra={"field": "check_out_date"})
        return _err("VALIDATION_ERROR", "check_out_date must be strictly after check_in_date", field="check_out_date")

    if adults is None:
        adults = 2
    if children is None:
        children = 0

    if not isinstance(adults, (int, float)) or not isinstance(children, (int, float)):
        _log("error", message="validation error", extra={"field": "adults/children"})
        return _err("VALIDATION_ERROR", "adults and children must be numbers")
    # enforce integer semantics
    if int(adults) != adults or int(children) != children:
        _log("error", message="validation error", extra={"field": "adults/children"})
        return _err("VALIDATION_ERROR", "adults and children must be integers")
    adults = int(adults)
    children = int(children)
    if adults < 1:
        _log("error", message="validation error", extra={"field": "adults"})
        return _err("VALIDATION_ERROR", "adults must be >= 1", field="adults")
    if children < 0:
        _log("error", message="validation error", extra={"field": "children"})
        return _err("VALIDATION_ERROR", "children must be >= 0", field="children")

    if name is not None and not isinstance(name, str):
        _log("error", message="validation error", extra={"field": "name"})
        return _err("VALIDATION_ERROR", "name must be a string if provided", field="name")
    if search_context is not None and not isinstance(search_context, str):
        _log("error", message="validation error", extra={"field": "search_context"})
        return _err("VALIDATION_ERROR", "search_context must be a string if provided", field="search_context")

    # facilities validation against facilities.external_facility_id where status=active
    facilities_rows = _load("facilities.json")
    if not isinstance(facilities_rows, list):
        facilities_rows = []
    active_external_ids = set()
    external_to_facility_id = {}
    for f in facilities_rows:
        if isinstance(f, dict) and f.get("status") == "active":
            eid = f.get("external_facility_id")
            if isinstance(eid, int) and eid > 0:
                active_external_ids.add(eid)
                external_to_facility_id[eid] = f.get("id")

    req_external_ids = None
    if facilities is not None:
        if not isinstance(facilities, list):
            _log("error", message="validation error", extra={"field": "facilities"})
            return _err("VALIDATION_ERROR", "facilities must be an array of numbers", field="facilities")
        req_external_ids = []
        for v in facilities:
            if not isinstance(v, (int, float)) or int(v) != v:
                _log("error", message="validation error", extra={"field": "facilities"})
                return _err("VALIDATION_ERROR", "facilities must contain integer IDs", field="facilities")
            v = int(v)
            if v not in active_external_ids:
                _log("error", message="validation error", extra={"field": "facilities", "value": v})
                return _err("VALIDATION_ERROR", "Unknown or inactive facility external_facility_id", field="facilities", value=v)
            req_external_ids.append(v)
        # de-duplicate, stable order
        seen = set()
        req_external_ids = [x for x in req_external_ids if not (x in seen or seen.add(x))]

    # ---- compute matches ----
    hotels = _load("hotels.json")
    if not isinstance(hotels, list):
        hotels = []

    hotel_fac = _load("hotel_facilities.json")
    if not isinstance(hotel_fac, list):
        hotel_fac = []

    # map hotel -> set of external facility ids available
    hotel_to_external = {}
    if req_external_ids:
        # build facility_id -> external id map
        facility_id_to_external = {}
        for f in facilities_rows:
            if isinstance(f, dict):
                fid = f.get("id")
                eid = f.get("external_facility_id")
                if isinstance(fid, str) and isinstance(eid, int):
                    facility_id_to_external[fid] = eid

        for hf in hotel_fac:
            if not isinstance(hf, dict):
                continue
            if hf.get("is_available") is not True:
                continue
            hid = hf.get("hotel_id")
            fid = hf.get("facility_id")
            if not isinstance(hid, str) or not isinstance(fid, str):
                continue
            eid = facility_id_to_external.get(fid)
            if eid is None:
                continue
            hotel_to_external.setdefault(hid, set()).add(eid)

    def _haversine_km(lat1, lon1, lat2, lon2):
        r = 6371.0
        p1 = math.radians(lat1); p2 = math.radians(lat2)
        dlat = p2 - p1
        dlon = math.radians(lon2 - lon1)
        a = math.sin(dlat/2)**2 + math.cos(p1)*math.cos(p2)*math.sin(dlon/2)**2
        return 2*r*math.asin(math.sqrt(a))

    name_filter = (name or "").strip().lower() if isinstance(name, str) else ""
    matched = []
    for h in hotels:
        if not isinstance(h, dict):
            continue
        if h.get("status") != "active":
            continue
        hlat = h.get("latitude")
        hlon = h.get("longitude")
        if not isinstance(hlat, (int, float)) or not isinstance(hlon, (int, float)):
            continue
        # basic radius: 50km
        dist = _haversine_km(latitude, longitude, float(hlat), float(hlon))
        if dist > 50.0:
            continue
        if name_filter:
            hn = (h.get("name") or "")
            hc = (h.get("city") or "")
            if not isinstance(hn, str): hn = ""
            if not isinstance(hc, str): hc = ""
            if name_filter not in hn.lower() and name_filter not in hc.lower():
                continue
        if req_external_ids:
            offered = hotel_to_external.get(h.get("id"), set())
            ok = all(eid in offered for eid in req_external_ids)
            if not ok:
                continue
        matched.append((dist, h))

    matched.sort(key=lambda x: (x[0], (x[1].get("star_rating") is None, -(x[1].get("star_rating") or 0)), (x[1].get("name") or "")))

    total = len(matched)
    page_size = min(50, max(1, 20))  # server default page size for this tool
    offset = 0
    page = matched[offset:offset+page_size]
    has_more = (offset + page_size) < total

    # ---- create search session ----
    sessions = _load("search_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    expires_at_dt = _now_dt + datetime.timedelta(minutes=30)
    expires_at = expires_at_dt.isoformat() + "Z"
    session_id = f"sess_{int(time.time()*1000)}_{random.randint(1000,9999)}"

    # Attempt to resolve query_place_id if name matches an active place.normalized_name (best-effort)
    query_place_id = None
    if name_filter:
        places = _load("places.json")
        if isinstance(places, list):
            for p in places:
                if isinstance(p, dict) and p.get("status") == "active":
                    nn = p.get("normalized_name")
                    if isinstance(nn, str) and nn == re.sub(r"\s+", " ", re.sub(r"[^\w\s\-']", "", name_filter)).strip():
                        query_place_id = p.get("id")
                        break

    sess_row = {
        "id": session_id,
        "query_place_id": query_place_id,
        "latitude": latitude,
        "longitude": longitude,
        "name": name if isinstance(name, str) else None,
        "check_in_date": check_in_date,
        "check_out_date": check_out_date,
        "adults": adults,
        "children": children,
        "search_context": search_context if isinstance(search_context, str) else None,
        "facility_external_ids": req_external_ids if req_external_ids is not None else None,
        "language": "en",
        "page_size": page_size,
        "next_offset": 0,
        "has_more": bool(has_more),
        "status": "active",
        "expires_at": expires_at,
        "created_at": _now,
        "updated_at": _now,
    }
    sessions.append(sess_row)
    _save("search_sessions.json", sessions)

    # ---- shape response hotels page ----
    hotels_out = []
    for dist, h in page:
        hotels_out.append({
            "id": h.get("id"),
            "name": h.get("name"),
            "address": {
                "address_line1": h.get("address_line1"),
                "address_line2": h.get("address_line2"),
                "city": h.get("city"),
                "region": h.get("region"),
                "postal_code": h.get("postal_code"),
                "country_code": h.get("country_code"),
            },
            "location": {"latitude": h.get("latitude"), "longitude": h.get("longitude")},
            "star_rating": h.get("star_rating"),
            "distance_km": round(dist, 2),
        })

    resp = {
        "session": {
            "id": session_id,
            "status": sess_row["status"],
            "expires_at": sess_row["expires_at"],
            "page_size": sess_row["page_size"],
            "next_offset": sess_row["next_offset"],
            "has_more": sess_row["has_more"],
        },
        "hotels": hotels_out,
        "meta": {"total": total, "returned": len(hotels_out)},
    }
    _log("ok", latency_ms=int((time.time() - _t0) * 1000))
    return resp

def load_more_hotels(session_id, **_extra):
    import json, os, datetime, time, random, math, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0017000" if __import__("os").path.isdir("./environment_mix/0017000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    _now = _now_dt.isoformat() + "Z"

    def _log(status, endpoint="load-more-hotels", message=None, extra=None, latency_ms=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            row = {
                "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
                "endpoint": endpoint,
                "status": status,
                "timestamp": _now,
                "latency_ms": latency_ms if latency_ms is not None else int((time.time() - _t0) * 1000),
            }
            if message is not None:
                row["message"] = message
            if isinstance(extra, dict) and extra:
                row["extra"] = extra
            logs.append(row)
            _save("request_logs.json", logs)

    if not isinstance(session_id, str) or not session_id.strip():
        _log("error", message="validation error", extra={"field": "session_id"})
        return _err("VALIDATION_ERROR", "session_id is required and must be a string", field="session_id")

    sessions = _load("search_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    sess = None
    sess_idx = None
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == session_id:
            sess = s
            sess_idx = i
            break
    if sess is None:
        _log("error", message="session not found")
        return _err("NOT_FOUND", "search session not found", session_id=session_id)

    # validate session status and expiry
    st = sess.get("status")
    if st != "active":
        # per rules: only operate on active; expired treated as NOT_FOUND in tool description
        code = "CONFLICT"
        if st in ("expired", "cancelled"):
            code = "NOT_FOUND"
        _log("error", message="invalid session state", extra={"status": st})
        return _err(code, "session is not active", status=st)

    exp = sess.get("expires_at")
    if not isinstance(exp, str):
        _log("error", message="invalid session expiry")
        return _err("CONFLICT", "session has invalid expires_at")
    try:
        exp_dt = datetime.datetime.fromisoformat(exp.replace("Z", "+00:00")).replace(tzinfo=None)
    except Exception:
        _log("error", message="invalid session expiry parse")
        return _err("CONFLICT", "session has invalid expires_at")
    if not (exp_dt > _now_dt):
        # transition to expired if legal
        sess["status"] = "expired"
        sess["has_more"] = False
        sess["updated_at"] = _now
        sessions[sess_idx] = sess
        _save("search_sessions.json", sessions)
        _log("error", message="session expired")
        return _err("NOT_FOUND", "search session expired", session_id=session_id)

    # Re-run the search deterministically using session filters
    lat = sess.get("latitude"); lon = sess.get("longitude")
    if not isinstance(lat, (int, float)) or not isinstance(lon, (int, float)):
        _log("error", message="invalid session coordinates")
        return _err("CONFLICT", "session has invalid coordinates")
    name = sess.get("name")
    name_filter = (name or "").strip().lower() if isinstance(name, str) else ""
    req_external_ids = sess.get("facility_external_ids")
    if req_external_ids is not None and not isinstance(req_external_ids, list):
        _log("error", message="invalid session facility filter")
        return _err("CONFLICT", "session has invalid facility_external_ids")

    hotels = _load("hotels.json")
    if not isinstance(hotels, list):
        hotels = []
    facilities_rows = _load("facilities.json")
    if not isinstance(facilities_rows, list):
        facilities_rows = []
    hotel_fac = _load("hotel_facilities.json")
    if not isinstance(hotel_fac, list):
        hotel_fac = []

    def _haversine_km(lat1, lon1, lat2, lon2):
        r = 6371.0
        p1 = math.radians(lat1); p2 = math.radians(lat2)
        dlat = p2 - p1
        dlon = math.radians(lon2 - lon1)
        a = math.sin(dlat/2)**2 + math.cos(p1)*math.cos(p2)*math.sin(dlon/2)**2
        return 2*r*math.asin(math.sqrt(a))

    hotel_to_external = {}
    if req_external_ids:
        facility_id_to_external = {}
        for f in facilities_rows:
            if isinstance(f, dict):
                fid = f.get("id")
                eid = f.get("external_facility_id")
                if isinstance(fid, str) and isinstance(eid, int):
                    facility_id_to_external[fid] = eid
        for hf in hotel_fac:
            if not isinstance(hf, dict):
                continue
            if hf.get("is_available") is not True:
                continue
            hid = hf.get("hotel_id")
            fid = hf.get("facility_id")
            if not isinstance(hid, str) or not isinstance(fid, str):
                continue
            eid = facility_id_to_external.get(fid)
            if eid is None:
                continue
            hotel_to_external.setdefault(hid, set()).add(eid)

    matched = []
    for h in hotels:
        if not isinstance(h, dict):
            continue
        if h.get("status") != "active":
            continue
        hlat = h.get("latitude"); hlon = h.get("longitude")
        if not isinstance(hlat, (int, float)) or not isinstance(hlon, (int, float)):
            continue
        dist = _haversine_km(float(lat), float(lon), float(hlat), float(hlon))
        if dist > 50.0:
            continue
        if name_filter:
            hn = (h.get("name") or "")
            hc = (h.get("city") or "")
            if not isinstance(hn, str): hn = ""
            if not isinstance(hc, str): hc = ""
            if name_filter not in hn.lower() and name_filter not in hc.lower():
                continue
        if req_external_ids:
            offered = hotel_to_external.get(h.get("id"), set())
            if not all(int(e) in offered for e in req_external_ids if isinstance(e, int)):
                continue
        matched.append((dist, h))

    matched.sort(key=lambda x: (x[0], (x[1].get("star_rating") is None, -(x[1].get("star_rating") or 0)), (x[1].get("name") or "")))

    total = len(matched)
    page_size = sess.get("page_size")
    next_offset = sess.get("next_offset")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 50:
        _log("error", message="invalid session page_size")
        return _err("CONFLICT", "session has invalid page_size")
    if not isinstance(next_offset, int) or next_offset < 0:
        _log("error", message="invalid session next_offset")
        return _err("CONFLICT", "session has invalid next_offset")

    offset = next_offset
    page = matched[offset:offset+page_size]
    if not page:
        # Exhaust results: transition active->exhausted
        sess["has_more"] = False
        if sess.get("status") == "active":
            sess["status"] = "exhausted"
        sess["updated_at"] = _now
        sessions[sess_idx] = sess
        _save("search_sessions.json", sessions)
        _log("ok", latency_ms=int((time.time() - _t0) * 1000))
        return {
            "session": {
                "id": sess["id"],
                "status": sess["status"],
                "expires_at": sess["expires_at"],
                "page_size": page_size,
                "next_offset": sess["next_offset"],
                "has_more": False,
            },
            "hotels": [],
            "meta": {"total": total, "returned": 0},
        }

    new_offset = offset + page_size
    has_more = new_offset < total

    sess["next_offset"] = new_offset
    sess["has_more"] = bool(has_more)
    if not has_more:
        sess["status"] = "exhausted"  # legal transition active->exhausted
    sess["updated_at"] = _now
    sessions[sess_idx] = sess
    _save("search_sessions.json", sessions)

    hotels_out = []
    for dist, h in page:
        hotels_out.append({
            "id": h.get("id"),
            "name": h.get("name"),
            "address": {
                "address_line1": h.get("address_line1"),
                "address_line2": h.get("address_line2"),
                "city": h.get("city"),
                "region": h.get("region"),
                "postal_code": h.get("postal_code"),
                "country_code": h.get("country_code"),
            },
            "location": {"latitude": h.get("latitude"), "longitude": h.get("longitude")},
            "star_rating": h.get("star_rating"),
            "distance_km": round(dist, 2),
        })

    resp = {
        "session": {
            "id": sess["id"],
            "status": sess["status"],
            "expires_at": sess["expires_at"],
            "page_size": page_size,
            "next_offset": sess["next_offset"],
            "has_more": sess["has_more"],
        },
        "hotels": hotels_out,
        "meta": {"total": total, "returned": len(hotels_out)},
    }
    _log("ok", latency_ms=int((time.time() - _t0) * 1000))
    return resp

def get_hotel_details(session_id, hotel_id, **_extra):
    import json, os, datetime, time, uuid, re, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0017000" if __import__("os").path.isdir("./environment_mix/0017000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-hotel-details"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_utc().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(float(s), tz=datetime.timezone.utc)
            except Exception:
                return None
        if not isinstance(s, str) or not s.strip():
            return None
        x = s.strip()
        try:
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(x)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_request_log():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _append_log(status, error_code=None, error_message=None):
        logs = _ensure_request_log()
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": int(status),
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "session_id": session_id,
            "hotel_id": hotel_id,
            "error_code": error_code,
            "error_message": error_message,
        })
        _save("request_logs.json", logs)

    def _enforce_rate_limit():
        cfg = _load("rate_limits.json")
        if not isinstance(cfg, dict):
            return True, None
        window_s = cfg.get("window_seconds", 60)
        max_req = cfg.get("max_requests_per_window", 120)
        if not isinstance(window_s, int) or window_s <= 0:
            window_s = 60
        if not isinstance(max_req, int) or max_req <= 0:
            max_req = 120

        logs = _ensure_request_log()
        now = _now_utc()
        cutoff = now - datetime.timedelta(seconds=window_s)

        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= cutoff:
                recent += 1
        if recent >= max_req:
            return False, _err("RATE_LIMIT", "rate limit exceeded", window_seconds=window_s, max_requests_per_window=max_req)
        return True, None

    # Validate input types
    if not isinstance(session_id, str) or not session_id.strip():
        _append_log(400, "VALIDATION_ERROR", "session_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "session_id must be a non-empty string")
    if not isinstance(hotel_id, str) or not hotel_id.strip():
        _append_log(400, "VALIDATION_ERROR", "hotel_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "hotel_id must be a non-empty string")
    session_id = session_id.strip()
    hotel_id = hotel_id.strip()

    ok, err = _enforce_rate_limit()
    if not ok:
        _append_log(429, err["error"]["code"], err["error"]["message"])
        return err

    sessions = _load("search_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    hotels = _load("hotels.json")
    if not isinstance(hotels, list):
        hotels = []
    facilities = _load("facilities.json")
    if not isinstance(facilities, list):
        facilities = []
    hotel_facilities = _load("hotel_facilities.json")
    if not isinstance(hotel_facilities, list):
        hotel_facilities = []

    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
    if not sess:
        _append_log(404, "NOT_FOUND", "search session not found")
        return _err("NOT_FOUND", "search session not found", session_id=session_id)

    now = _now_utc()
    expires_at = _parse_dt(sess.get("expires_at"))

    # Business rule: must only allow session_id that exists and is not expired/cancelled
    # (Note: allow exhausted as "not cancelled/expired" to avoid false negatives; details are still valid.)
    if sess.get("status") == "cancelled":
        _append_log(404, "NOT_FOUND", "search session cancelled (business rule: session must not be cancelled)")
        return _err("NOT_FOUND", "search session cancelled (business rule: session must not be cancelled)", session_id=session_id, status=sess.get("status"))
    if expires_at is not None and expires_at <= now:
        # If session row is still marked active/exhausted but time passed, transition to expired per lifecycle.
        if sess.get("status") in ("active", "exhausted"):
            allowed = {"active": ["exhausted", "expired", "cancelled"], "exhausted": ["expired"]}.get(sess.get("status"), [])
            if "expired" in allowed:
                sess["status"] = "expired"
                sess["updated_at"] = _now_iso()
                _save("search_sessions.json", sessions)
        _append_log(404, "NOT_FOUND", "search session expired (business rule: session must not be expired)")
        return _err("NOT_FOUND", "search session expired (business rule: session must not be expired)", session_id=session_id, status=sess.get("status"))

    htl = next((h for h in hotels if isinstance(h, dict) and h.get("id") == hotel_id), None)
    if not htl:
        _append_log(404, "NOT_FOUND", "hotel not found")
        return _err("NOT_FOUND", "hotel not found", hotel_id=hotel_id)
    if htl.get("status") != "active":
        _append_log(404, "NOT_FOUND", "hotel not available (business rule: hotel must be active)")
        return _err("NOT_FOUND", "hotel not available (business rule: hotel must be active)", hotel_id=hotel_id, status=htl.get("status"))

    # Ensure hotel is part of the session result set as of the session filters.
    # Recompute filters used by search-hotels (location radius is not specified, so we use:
    # - optional name substring match
    # - required facilities filter
    # - active hotel status (already checked)
    req_fac_ext_ids = sess.get("facility_external_ids")
    if req_fac_ext_ids is not None and not isinstance(req_fac_ext_ids, list):
        _append_log(400, "VALIDATION_ERROR", "session has invalid facility_external_ids type")
        return _err("VALIDATION_ERROR", "session has invalid facility_external_ids type", session_id=session_id)

    # validate requested facilities exist + active and map to facility ids
    ext_to_fac = {}
    for f in facilities:
        if not isinstance(f, dict):
            continue
        if f.get("status") != "active":
            continue
        ext = f.get("external_facility_id")
        if isinstance(ext, int):
            ext_to_fac[ext] = f.get("id")
    req_fac_ids = []
    if isinstance(req_fac_ext_ids, list) and req_fac_ext_ids:
        for x in req_fac_ext_ids:
            if not isinstance(x, int):
                _append_log(400, "VALIDATION_ERROR", "session has invalid facility_external_ids value type")
                return _err("VALIDATION_ERROR", "session has invalid facility_external_ids value type", session_id=session_id)
            fid = ext_to_fac.get(x)
            if not fid:
                _append_log(400, "VALIDATION_ERROR", "session references unknown/inactive facility_external_id")
                return _err("VALIDATION_ERROR", "session references unknown/inactive facility_external_id", session_id=session_id, external_facility_id=x)
            req_fac_ids.append(fid)

    # Check name filter
    name_filter = sess.get("name")
    if name_filter is not None and not isinstance(name_filter, str):
        name_filter = None
    if name_filter:
        nf = name_filter.strip().lower()
        if nf and nf not in str(htl.get("name", "")).lower():
            _append_log(404, "NOT_FOUND", "hotel not in session results (business rule: hotel must be part of the session result set)")
            return _err("NOT_FOUND", "hotel not in session results (business rule: hotel must be part of the session result set)", session_id=session_id, hotel_id=hotel_id)

    # Check facilities filter: hotel must have all requested facilities is_available=true
    if req_fac_ids:
        offered = set()
        for hf in hotel_facilities:
            if not isinstance(hf, dict):
                continue
            if hf.get("hotel_id") != hotel_id:
                continue
            if hf.get("is_available") is True:
                fid = hf.get("facility_id")
                if isinstance(fid, str):
                    offered.add(fid)
        for fid in req_fac_ids:
            if fid not in offered:
                _append_log(404, "NOT_FOUND", "hotel not in session results (business rule: hotel must satisfy session facility filters)")
                return _err("NOT_FOUND", "hotel not in session results (business rule: hotel must satisfy session facility filters)", session_id=session_id, hotel_id=hotel_id)

    # Build amenities list
    fac_by_id = {f.get("id"): f for f in facilities if isinstance(f, dict)}
    amenities = []
    for hf in hotel_facilities:
        if not isinstance(hf, dict):
            continue
        if hf.get("hotel_id") != hotel_id:
            continue
        fid = hf.get("facility_id")
        fac = fac_by_id.get(fid)
        if not fac or fac.get("status") != "active":
            continue
        amenities.append({
            "facility_id": fid,
            "external_facility_id": fac.get("external_facility_id"),
            "name": (fac.get("localized_names") or {}).get(sess.get("language")) if isinstance(fac.get("localized_names"), dict) else None,
            "default_name": fac.get("default_name"),
            "category": fac.get("category"),
            "is_available": hf.get("is_available") is True,
            "notes": hf.get("notes"),
        })
    for a in amenities:
        if not a.get("name"):
            a["name"] = a.get("default_name")

    # Generate deterministic rate options accepted by book-hotel.rate_id.
    # Use session params so rate_id remains stable for the session+hotel.
    def _safe(s):
        s = "" if s is None else str(s)
        return re.sub(r"[^A-Za-z0-9]+", "_", s).strip("_")[:80] or "X"

    sess_currency = "USD"
    cc = htl.get("country_code")
    if isinstance(cc, str) and cc.upper() in ("US",):
        sess_currency = "USD"
    elif isinstance(cc, str) and cc.upper() in ("GB",):
        sess_currency = "GBP"
    else:
        # default to EUR for many non-US/GB
        sess_currency = "EUR"

    check_in = sess.get("check_in_date")
    check_out = sess.get("check_out_date")
    adults = sess.get("adults")
    children = sess.get("children")
    try:
        d1 = datetime.date.fromisoformat(check_in)
        d2 = datetime.date.fromisoformat(check_out)
        nights = (d2 - d1).days
        if nights <= 0:
            nights = 1
    except Exception:
        nights = 1

    occ = 0
    if isinstance(adults, int):
        occ += adults
    if isinstance(children, int):
        occ += children
    if occ <= 0:
        occ = 1

    base = 80.0 + (10.0 * max(0, float(htl.get("star_rating") or 0))) + (15.0 * max(0, occ - 1))
    total_flex = round(base * nights * 1.15, 2)
    total_nonref = round(base * nights * 0.95, 2)

    # Provide at least two options; ids include enough info to validate later.
    rate_options = [
        {
            "rate_id": f"rt_hb_{sess_currency}_{_safe(session_id)}_FLEX_STD_{check_in}_{occ}P",
            "currency": sess_currency,
            "total_price": total_flex,
            "refundable": True,
            "meal_plan": "room_only",
            "cancellation_policy": {"type": "flexible", "free_cancellation_until": check_in},
            "payment_policy": {"type": "pay_now"},
        },
        {
            "rate_id": f"rt_hb_{sess_currency}_{_safe(session_id)}_NRF_STD_{check_in}_{occ}P",
            "currency": sess_currency,
            "total_price": total_nonref,
            "refundable": False,
            "meal_plan": "room_only",
            "cancellation_policy": {"type": "non_refundable"},
            "payment_policy": {"type": "pay_now"},
        },
    ]

    body = {
        "session": {
            "id": sess.get("id"),
            "status": sess.get("status"),
            "expires_at": sess.get("expires_at"),
            "language": sess.get("language"),
            "check_in_date": sess.get("check_in_date"),
            "check_out_date": sess.get("check_out_date"),
            "adults": sess.get("adults"),
            "children": sess.get("children"),
            "facility_external_ids": sess.get("facility_external_ids"),
        },
        "hotel": {
            "id": htl.get("id"),
            "source": htl.get("source"),
            "source_hotel_id": htl.get("source_hotel_id"),
            "name": htl.get("name"),
            "description": htl.get("description"),
            "address": {
                "address_line1": htl.get("address_line1"),
                "address_line2": htl.get("address_line2"),
                "city": htl.get("city"),
                "region": htl.get("region"),
                "postal_code": htl.get("postal_code"),
                "country_code": htl.get("country_code"),
            },
            "location": {"latitude": htl.get("latitude"), "longitude": htl.get("longitude")},
            "star_rating": htl.get("star_rating"),
            "check_in_time": htl.get("check_in_time"),
            "check_out_time": htl.get("check_out_time"),
            "amenities": amenities,
        },
        "rates": rate_options,
    }

    _append_log(200, None, None)
    return body

def book_hotel(session_id, hotel_id, rate_id, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0017000" if __import__("os").path.isdir("./environment_mix/0017000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "book-hotel"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_utc().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(float(s), tz=datetime.timezone.utc)
            except Exception:
                return None
        if not isinstance(s, str) or not s.strip():
            return None
        x = s.strip()
        try:
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(x)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_request_log():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _append_log(status, error_code=None, error_message=None, booking_id=None):
        logs = _ensure_request_log()
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": int(status),
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "session_id": session_id,
            "hotel_id": hotel_id,
            "rate_id": rate_id,
            "booking_id": booking_id,
            "error_code": error_code,
            "error_message": error_message,
        })
        _save("request_logs.json", logs)

    def _enforce_rate_limit():
        cfg = _load("rate_limits.json")
        if not isinstance(cfg, dict):
            return True, None
        window_s = cfg.get("window_seconds", 60)
        max_req = cfg.get("max_requests_per_window", 120)
        if not isinstance(window_s, int) or window_s <= 0:
            window_s = 60
        if not isinstance(max_req, int) or max_req <= 0:
            max_req = 120

        logs = _ensure_request_log()
        now = _now_utc()
        cutoff = now - datetime.timedelta(seconds=window_s)

        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= cutoff:
                recent += 1
        if recent >= max_req:
            return False, _err("RATE_LIMIT", "rate limit exceeded", window_seconds=window_s, max_requests_per_window=max_req)
        return True, None

    # Validate input types
    if not isinstance(session_id, str) or not session_id.strip():
        _append_log(400, "VALIDATION_ERROR", "session_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "session_id must be a non-empty string")
    if not isinstance(hotel_id, str) or not hotel_id.strip():
        _append_log(400, "VALIDATION_ERROR", "hotel_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "hotel_id must be a non-empty string")
    if not isinstance(rate_id, str) or not rate_id.strip():
        _append_log(400, "VALIDATION_ERROR", "rate_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "rate_id must be a non-empty string")
    session_id = session_id.strip()
    hotel_id = hotel_id.strip()
    rate_id = rate_id.strip()

    ok, err = _enforce_rate_limit()
    if not ok:
        _append_log(429, err["error"]["code"], err["error"]["message"])
        return err

    sessions = _load("search_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    hotels = _load("hotels.json")
    if not isinstance(hotels, list):
        hotels = []
    facilities = _load("facilities.json")
    if not isinstance(facilities, list):
        facilities = []
    hotel_facilities = _load("hotel_facilities.json")
    if not isinstance(hotel_facilities, list):
        hotel_facilities = []
    bookings = _load("bookings.json")
    if not isinstance(bookings, list):
        bookings = []

    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
    if not sess:
        _append_log(404, "NOT_FOUND", "search session not found")
        return _err("NOT_FOUND", "search session not found", session_id=session_id)

    now = _now_utc()
    expires_at = _parse_dt(sess.get("expires_at"))

    # Business rule: reject if expired/cancelled (do not misclassify)
    if sess.get("status") == "cancelled":
        _append_log(404, "NOT_FOUND", "search session cancelled (business rule: session must not be cancelled)")
        return _err("NOT_FOUND", "search session cancelled (business rule: session must not be cancelled)", session_id=session_id, status=sess.get("status"))
    if expires_at is not None and expires_at <= now:
        if sess.get("status") in ("active", "exhausted"):
            allowed = {"active": ["exhausted", "expired", "cancelled"], "exhausted": ["expired"]}.get(sess.get("status"), [])
            if "expired" in allowed:
                sess["status"] = "expired"
                sess["updated_at"] = _now_iso()
                _save("search_sessions.json", sessions)
        _append_log(404, "NOT_FOUND", "search session expired (business rule: session must not be expired)")
        return _err("NOT_FOUND", "search session expired (business rule: session must not be expired)", session_id=session_id, status=sess.get("status"))

    htl = next((h for h in hotels if isinstance(h, dict) and h.get("id") == hotel_id), None)
    if not htl:
        _append_log(404, "NOT_FOUND", "hotel not found")
        return _err("NOT_FOUND", "hotel not found", hotel_id=hotel_id)
    if htl.get("status") != "active":
        _append_log(404, "NOT_FOUND", "hotel not available (business rule: hotel must be active)")
        return _err("NOT_FOUND", "hotel not available (business rule: hotel must be active)", hotel_id=hotel_id, status=htl.get("status"))

    # Recompute whether hotel is in session result set (same as get-hotel-details)
    req_fac_ext_ids = sess.get("facility_external_ids")
    if req_fac_ext_ids is not None and not isinstance(req_fac_ext_ids, list):
        _append_log(400, "VALIDATION_ERROR", "session has invalid facility_external_ids type")
        return _err("VALIDATION_ERROR", "session has invalid facility_external_ids type", session_id=session_id)

    ext_to_fac = {}
    for f in facilities:
        if not isinstance(f, dict):
            continue
        if f.get("status") != "active":
            continue
        ext = f.get("external_facility_id")
        if isinstance(ext, int):
            ext_to_fac[ext] = f.get("id")
    req_fac_ids = []
    if isinstance(req_fac_ext_ids, list) and req_fac_ext_ids:
        for x in req_fac_ext_ids:
            if not isinstance(x, int):
                _append_log(400, "VALIDATION_ERROR", "session has invalid facility_external_ids value type")
                return _err("VALIDATION_ERROR", "session has invalid facility_external_ids value type", session_id=session_id)
            fid = ext_to_fac.get(x)
            if not fid:
                _append_log(400, "VALIDATION_ERROR", "session references unknown/inactive facility_external_id")
                return _err("VALIDATION_ERROR", "session references unknown/inactive facility_external_id", session_id=session_id, external_facility_id=x)
            req_fac_ids.append(fid)

    name_filter = sess.get("name")
    if name_filter is not None and not isinstance(name_filter, str):
        name_filter = None
    if name_filter:
        nf = name_filter.strip().lower()
        if nf and nf not in str(htl.get("name", "")).lower():
            _append_log(404, "NOT_FOUND", "hotel not in session results (business rule: hotel must be part of the session result set)")
            return _err("NOT_FOUND", "hotel not in session results (business rule: hotel must be part of the session result set)", session_id=session_id, hotel_id=hotel_id)

    if req_fac_ids:
        offered = set()
        for hf in hotel_facilities:
            if not isinstance(hf, dict):
                continue
            if hf.get("hotel_id") != hotel_id:
                continue
            if hf.get("is_available") is True:
                fid = hf.get("facility_id")
                if isinstance(fid, str):
                    offered.add(fid)
        for fid in req_fac_ids:
            if fid not in offered:
                _append_log(404, "NOT_FOUND", "hotel not in session results (business rule: hotel must satisfy session facility filters)")
                return _err("NOT_FOUND", "hotel not in session results (business rule: hotel must satisfy session facility filters)", session_id=session_id, hotel_id=hotel_id)

    # Validate that rate_id belongs to the given hotel in the given session:
    # Accept any rate_id that was produced by get-hotel-details rate generator for this session.
    # Our generated ids include the session_id token; additionally accept rate_ids that start with "rt_" and contain the session id token.
    if session_id not in rate_id or not rate_id.startswith("rt_"):
        _append_log(404, "NOT_FOUND", "rate not found in session/hotel context (business rule: rate_id must belong to hotel in session)")
        return _err("NOT_FOUND", "rate not found in session/hotel context (business rule: rate_id must belong to hotel in session)", session_id=session_id, hotel_id=hotel_id, rate_id=rate_id)

    # Prevent duplicate active booking attempts for statuses in ('initiated','payment_pending','paid')
    active_statuses = {"initiated", "payment_pending", "paid"}
    for b in bookings:
        if not isinstance(b, dict):
            continue
        if b.get("session_id") == session_id and b.get("hotel_id") == hotel_id and b.get("rate_id") == rate_id and b.get("status") in active_statuses:
            _append_log(200, None, None, booking_id=b.get("id"))
            return {"booking": b}

    # Create booking row: initiated -> payment_pending only after payment link generated
    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:26]}"

    # Determine currency/price heuristically from rate_id (if present)
    currency = None
    m = re.search(r"^rt_[A-Za-z0-9]+_([A-Z]{3})_", rate_id)
    if m:
        currency = m.group(1)

    # Quote total_price (best-effort; real vendor would quote from upstream)
    # Keep non-negative.
    total_price = None
    if currency:
        total_price = 0.0
        # lightweight deterministic quote
        try:
            # derive a stable number from ids
            seed = sum(ord(c) for c in (session_id + hotel_id + rate_id)) % 1000
            total_price = round(50.0 + seed / 10.0, 2)
        except Exception:
            total_price = 100.0

    created_iso = _now_iso()
    booking = {
        "id": _gen_id("bk"),
        "session_id": session_id,
        "hotel_id": hotel_id,
        "rate_id": rate_id,
        "check_in_date": sess.get("check_in_date"),
        "check_out_date": sess.get("check_out_date"),
        "adults": sess.get("adults"),
        "children": sess.get("children"),
        "payment_link_url": None,
        "payment_link_expires_at": None,
        "currency": currency,
        "total_price": total_price,
        "status": "initiated",
        "failure_reason": None,
        "provider_booking_id": None,
        "provider_payload": None,
        "created_at": created_iso,
        "updated_at": created_iso,
    }

    # Generate payment link and expiry; must not outlive session
    # Use min(now+15m, session_expires_at) and must be > now.
    session_exp = expires_at
    pl_exp = now + datetime.timedelta(minutes=15)
    if session_exp is not None and pl_exp > session_exp:
        pl_exp = session_exp
    if pl_exp <= now:
        booking["status"] = "failed"
        booking["failure_reason"] = "payment_link_expired_before_issue"
        booking["updated_at"] = _now_iso()
        bookings.append(booking)
        _save("bookings.json", bookings)
        _append_log(409, "CONFLICT", "cannot generate payment link within session expiry (business rule: payment link cannot outlive the search session context)", booking_id=booking["id"])
        return _err("CONFLICT", "cannot generate payment link within session expiry (business rule: payment link cannot outlive the search session context)", session_id=session_id, booking_id=booking["id"])

    booking["payment_link_url"] = f"https://pay.local/checkout/{booking['id']}?token={uuid.uuid4().hex}"
    booking["payment_link_expires_at"] = pl_exp.isoformat().replace("+00:00", "Z")
    booking["status"] = "payment_pending"
    booking["updated_at"] = _now_iso()

    bookings.append(booking)
    _save("bookings.json", bookings)

    _append_log(200, None, None, booking_id=booking["id"])
    return {"booking": booking}

