        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-facilities"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso_z(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
                return dt
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix, existing_ids):
        import random
        for _ in range(50):
            raw = f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{random.getrandbits(48):012x}"
            if raw not in existing_ids:
                return raw
        return None

    def _log_call(outcome_code):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("req", set([r.get("id") for r in logs if isinstance(r, dict)])),
            "endpoint": endpoint,
            "credential": "ambient",
            "status": outcome_code,
            "latency_ms": int(round((time.time() - t0) * 1000)),
            "timestamp": _now_iso()
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        bucket = "ambient"
        one_min_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("credential") != bucket:
                continue
            ts = _parse_iso_z(r.get("timestamp"))
            if not ts:
                continue
            if ts >= one_min_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1
        if per_min >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if per_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    if language is None:
        language = "en"
    if not isinstance(language, str):
        e = _err("VALIDATION_ERROR", "language must be a string", field="language")
        _log_call("VALIDATION_ERROR")
        return e
    language = language.strip()
    allowed = set(["en", "es", "it", "he", "ar", "de"])
    if language not in allowed:
        e = _err("VALIDATION_ERROR", "Unsupported language", field="language", allowed=sorted(list(allowed)))
        _log_call("VALIDATION_ERROR")
        return e

    lim = _enforce_limits()
    if lim:
        _log_call(lim["error"]["code"])
        return lim

    facilities = _load("facilities.json")
    if not isinstance(facilities, list):
        facilities = []

    out = []
    for f in facilities:
        if not isinstance(f, dict):
            continue
        if f.get("status") != "active":
            continue
        loc = f.get("localized_names")
        name = None
        if isinstance(loc, dict) and language in loc and isinstance(loc.get(language), str) and loc.get(language).strip():
            name = loc.get(language).strip()
        else:
            dn = f.get("default_name")
            if isinstance(dn, str) and dn.strip():
                name = dn.strip()
        out.append({
            "id": f.get("id"),
            "external_facility_id": f.get("external_facility_id"),
            "category": f.get("category"),
            "name": name
        })

    out.sort(key=lambda x: (str(x.get("category") or ""), str(x.get("name") or ""), str(x.get("id") or "")))

    _log_call("ok")
    return {"language": language, "facilities": out, "total": len(out)}

