def cancel_search_session(session_id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0017000" if __import__("os").path.isdir("./environment_mix/0017000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "cancel-search-session"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_utc().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        x = s.strip()
        try:
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(x)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_request_log():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _append_log(status, error_code=None, error_message=None):
        logs = _ensure_request_log()
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": int(status),
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "session_id": session_id,
            "error_code": error_code,
            "error_message": error_message,
        })
        _save("request_logs.json", logs)

    def _rate_limit_ok():
        cfg = _load("rate_limits.json")
        if not isinstance(cfg, dict):
            return True, None
        window_s = cfg.get("window_seconds", 60)
        max_req = cfg.get("max_requests_per_window", 120)
        if not isinstance(window_s, int) or window_s <= 0:
            window_s = 60
        if not isinstance(max_req, int) or max_req <= 0:
            max_req = 120
        logs = _ensure_request_log()
        now = _now_utc()
        cutoff = now - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in reversed(logs[-3000:]):
            if not isinstance(r, dict):
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None or ts < cutoff:
                continue
            cnt += 1
            if cnt >= max_req:
                return False, _err("RATE_LIMIT", "Rate limit exceeded")
        return True, None

    if not isinstance(session_id, str) or not session_id.strip():
        _append_log(400, "VALIDATION_ERROR", "session_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "session_id must be a non-empty string", session_id=session_id)

    ok, rl_err = _rate_limit_ok()
    if not ok:
        _append_log(429, rl_err["error"]["code"], rl_err["error"]["message"])
        return rl_err

    sessions = _load("search_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    idx = None
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == session_id:
            idx = i
            break
    if idx is None:
        _append_log(404, "NOT_FOUND", "search session not found")
        return _err("NOT_FOUND", "search session not found", session_id=session_id)

    sess = sessions[idx]
    status = sess.get("status")

    # Realistic behavior: if already cancelled -> idempotent success returning session (many APIs do this),
    # but description says CONFLICT for already exhausted/expired/cancelled. We'll follow description for exhausted/expired,
    # but keep idempotent success for cancelled to avoid retried cancel failing.
    if status == "cancelled":
        _append_log(200)
        return {"session": sess}

    # Only allow transition active -> cancelled. Exhausted/expired are conflict.
    if status != "active":
        _append_log(409, "CONFLICT", "session cannot be cancelled unless status='active' (business rule: only active sessions can be cancelled)")
        return _err("CONFLICT", "session cannot be cancelled unless status='active' (business rule: only active sessions can be cancelled)", session_id=session_id, status=status)

    sess["status"] = "cancelled"
    sess["has_more"] = False
    sess["updated_at"] = _now_iso()
    sessions[idx] = sess
    _save("search_sessions.json", sessions)

    _append_log(200)
    return {"session": sess}

def list_bookings(session_id=None, hotel_id=None, status=None, page_size=None, page_token=None, created_after=None, created_before=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0017000" if __import__("os").path.isdir("./environment_mix/0017000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=None)
            return datetime.datetime.fromisoformat(s).replace(tzinfo=None)
        except Exception:
            return None

    def _get_caller_credential():
        candidates = []
        for fname in ("api_keys.json", "keys.json", "credentials.json"):
            rows = _load(fname)
            if isinstance(rows, list) and rows:
                for r in rows:
                    if isinstance(r, dict):
                        st = r.get("status")
                        if st in (None, "active", "enabled", "valid"):
                            candidates.append((fname, r))
        return candidates[0] if candidates else (None, None)

    def _log_and_maybe_limit(endpoint, phase, status_code, msg, cred_row):
        log_file = None
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            log_file = fname
            break

        cred_id = None
        if isinstance(cred_row, dict):
            cred_id = cred_row.get("id") or cred_row.get("key_id") or cred_row.get("credential_id")
        if not cred_id:
            cred_id = "anonymous"

        logs = _load(log_file) if log_file else []
        if not isinstance(logs, list):
            logs = []

        one_min_ago = now - datetime.timedelta(seconds=60)
        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)

        def _dt_from_row(r):
            return _parse_rfc3339(r.get("timestamp") or r.get("created_at"))

        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if (r.get("credential_id") or r.get("cred_id") or r.get("api_key_id") or "anonymous") != cred_id:
                continue
            ts = _dt_from_row(r)
            if not ts:
                continue
            if ts >= one_min_ago:
                per_min += 1
            if ts >= day_start:
                per_day += 1

        if per_min >= 120:
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "credential_id": cred_id,
                "status": "RATE_LIMIT",
                "http_status": 429,
                "message": "Rate limit exceeded",
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now_iso,
                "phase": phase
            })
            _save(log_file, logs)
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if per_day >= 5000:
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "credential_id": cred_id,
                "status": "QUOTA_EXCEEDED",
                "http_status": 429,
                "message": "Daily quota exceeded",
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now_iso,
                "phase": phase
            })
            _save(log_file, logs)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_id": cred_id,
            "status": status_code,
            "http_status": 200 if status_code == "OK" else 400,
            "message": msg,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
            "phase": phase
        })
        _save(log_file, logs)
        return None

    _, cred_row = _get_caller_credential()
    lim = _log_and_maybe_limit("list-bookings", "precheck", "OK_PRECHECK", "precheck", cred_row)
    if isinstance(lim, dict) and lim.get("error"):
        return lim

    # ---- validate inputs ----
    if session_id is not None and (not isinstance(session_id, str) or not session_id.strip()):
        err = _err("VALIDATION_ERROR", "session_id must be a non-empty string when provided")
        _log_and_maybe_limit("list-bookings", "final", "VALIDATION_ERROR", err["error"]["message"], cred_row)
        return err
    if hotel_id is not None and (not isinstance(hotel_id, str) or not hotel_id.strip()):
        err = _err("VALIDATION_ERROR", "hotel_id must be a non-empty string when provided")
        _log_and_maybe_limit("list-bookings", "final", "VALIDATION_ERROR", err["error"]["message"], cred_row)
        return err
    allowed_status = {"initiated", "payment_pending", "paid", "confirmed", "cancelled", "expired", "failed"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            err = _err("VALIDATION_ERROR", "Invalid status filter", allowed=list(sorted(allowed_status)))
            _log_and_maybe_limit("list-bookings", "final", "VALIDATION_ERROR", err["error"]["message"], cred_row)
            return err

    if page_size is None:
        page_size = 20
    if not isinstance(page_size, int) or page_size < 1 or page_size > 50:
        err = _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 50")
        _log_and_maybe_limit("list-bookings", "final", "VALIDATION_ERROR", err["error"]["message"], cred_row)
        return err

    ca = _parse_rfc3339(created_after)
    if created_after is not None and ca is None:
        err = _err("VALIDATION_ERROR", "created_after must be RFC 3339 timestamp")
        _log_and_maybe_limit("list-bookings", "final", "VALIDATION_ERROR", err["error"]["message"], cred_row)
        return err
    cb = _parse_rfc3339(created_before)
    if created_before is not None and cb is None:
        err = _err("VALIDATION_ERROR", "created_before must be RFC 3339 timestamp")
        _log_and_maybe_limit("list-bookings", "final", "VALIDATION_ERROR", err["error"]["message"], cred_row)
        return err
    if ca and cb and cb <= ca:
        err = _err("VALIDATION_ERROR", "created_before must be after created_after")
        _log_and_maybe_limit("list-bookings", "final", "VALIDATION_ERROR", err["error"]["message"], cred_row)
        return err

    # page_token is an opaque cursor; we use base64("offset:<n>")
    offset = 0
    if page_token is not None:
        if not isinstance(page_token, str) or not page_token.strip():
            err = _err("VALIDATION_ERROR", "page_token must be a non-empty string when provided")
            _log_and_maybe_limit("list-bookings", "final", "VALIDATION_ERROR", err["error"]["message"], cred_row)
            return err
        try:
            padded = page_token + ("=" * ((4 - (len(page_token) % 4)) % 4))
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                raise ValueError("bad token")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError("bad offset")
        except Exception:
            err = _err("VALIDATION_ERROR", "Invalid page_token")
            _log_and_maybe_limit("list-bookings", "final", "VALIDATION_ERROR", err["error"]["message"], cred_row)
            return err

    # ---- load and filter ----
    rows = _load("bookings.json")
    if not isinstance(rows, list):
        rows = []

    def _created_dt(r):
        return _parse_rfc3339(r.get("created_at")) or datetime.datetime.min

    filtered = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if session_id is not None and r.get("session_id") != session_id:
            continue
        if hotel_id is not None and r.get("hotel_id") != hotel_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        cdt = _created_dt(r)
        if ca and not (cdt > ca):
            continue
        if cb and not (cdt < cb):
            continue
        filtered.append(r)

    filtered.sort(key=_created_dt, reverse=True)

    total = len(filtered)
    page = filtered[offset: offset + page_size]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_token = None
    if has_more:
        next_token = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "bookings": page,
        "page_size": page_size,
        "total": total,
        "has_more": has_more,
        "next_page_token": next_token
    }

    _log_and_maybe_limit("list-bookings", "final", "OK", "ok", cred_row)
    return resp

