        max_req = cfg.get("max_requests_per_window", 120)
        if not isinstance(window_s, int) or window_s <= 0:
            window_s = 60
        if not isinstance(max_req, int) or max_req <= 0:
            max_req = 120
        logs = _ensure_request_log()
        now = _now_utc()
        cutoff = now - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in reversed(logs[-3000:]):
            if not isinstance(r, dict):
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None or ts < cutoff:
                continue
            cnt += 1
            if cnt >= max_req:
                return False, _err("RATE_LIMIT", "Rate limit exceeded")
        return True, None

    def _log(ok, status, error_code=None, error_message=None):
        logs = _ensure_request_log()
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential": "ambient",
            "ok": bool(ok),
            "status": int(status),
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "booking_id": booking_id
        })
        _save("request_logs.json", logs)

    ok_rl, rl_err = _rate_limit_ok()
    if not ok_rl:
        _log(False, 429, rl_err["error"]["code"], rl_err["error"]["message"])
        return rl_err

    if not isinstance(booking_id, str) or not booking_id.strip():
        err = _err("VALIDATION_ERROR", "booking_id must be a non-empty string", field="booking_id")
        _log(False, 400, err["error"]["code"], err["error"]["message"])
        return err

    bookings = _load("bookings.json")
    if not isinstance(bookings, list):
        bookings = []

    # Accept either primary key id (bk_...) OR provider_booking_id (HBK_..., EXP_..., etc)
    booking = None
    for b in bookings:
        if not isinstance(b, dict):
            continue
        if b.get("id") == booking_id or b.get("provider_booking_id") == booking_id:
            booking = b
            break

    if booking is None:
        err = _err("NOT_FOUND", "Booking not found", booking_id=booking_id)
        _log(False, 404, err["error"]["code"], err["error"]["message"])
        return err

    _log(True, 200)
    return {"booking": booking}

def cancel_booking(booking_id, reason=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0017000" if __import__("os").path.isdir("./environment_mix/0017000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "cancel-booking"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_utc().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        x = s.strip()
        try:
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(x)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_request_log():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _rate_limit_ok():
        cfg = _load("rate_limits.json")
        if not isinstance(cfg, dict):
            return True, None
        window_s = cfg.get("window_seconds", 60)
        max_req = cfg.get("max_requests_per_window", 120)
        if not isinstance(window_s, int) or window_s <= 0:
            window_s = 60
        if not isinstance(max_req, int) or max_req <= 0:
            max_req = 120
        logs = _ensure_request_log()
        now = _now_utc()
        cutoff = now - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in reversed(logs[-3000:]):
            if not isinstance(r, dict):
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None or ts < cutoff:
                continue
            cnt += 1
            if cnt >= max_req:
                return False, _err("RATE_LIMIT", "Rate limit exceeded")
        return True, None

    def _log(ok, status, error_code=None, error_message=None, resolved_id=None):
        logs = _ensure_request_log()
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential": "ambient",
            "ok": bool(ok),
            "status": int(status),
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "booking_id": booking_id,
            "resolved_booking_id": resolved_id
        })
        _save("request_logs.json", logs)

    ok_rl, rl_err = _rate_limit_ok()
    if not ok_rl:
        _log(False, 429, rl_err["error"]["code"], rl_err["error"]["message"])
        return rl_err

    if not isinstance(booking_id, str) or not booking_id.strip():
        err = _err("VALIDATION_ERROR", "booking_id must be a non-empty string", field="booking_id")
        _log(False, 400, err["error"]["code"], err["error"]["message"])
        return err
    if reason is not None and not isinstance(reason, str):
        err = _err("VALIDATION_ERROR", "reason must be a string when provided", field="reason")
        _log(False, 400, err["error"]["code"], err["error"]["message"])
        return err

    bookings = _load("bookings.json")
    if not isinstance(bookings, list):
        bookings = []

    idx = None
    for i, b in enumerate(bookings):
        if not isinstance(b, dict):
            continue
        if b.get("id") == booking_id or b.get("provider_booking_id") == booking_id:
            idx = i
            break

    if idx is None:
        err = _err("NOT_FOUND", "Booking not found", booking_id=booking_id)
        _log(False, 404, err["error"]["code"], err["error"]["message"])
        return err

    booking = bookings[idx]
    st = booking.get("status")

    # Lifecycle: allow cancel from initiated, payment_pending, confirmed
    if st not in ("initiated", "payment_pending", "confirmed"):
        err = _err("CONFLICT", "Booking cannot be cancelled from its current status (lifecycle rule)", booking_id=booking_id, status=st)
        _log(False, 409, err["error"]["code"], err["error"]["message"], resolved_id=booking.get("id"))
        return err

    booking["status"] = "cancelled"
    if isinstance(reason, str) and reason.strip():
        booking["failure_reason"] = reason.strip()
    booking["updated_at"] = _now_iso()
    bookings[idx] = booking
    _save("bookings.json", bookings)

    _log(True, 200, resolved_id=booking.get("id"))
    return {"booking": booking}
